mapper.select:

inner join walk_record_likes profile_like on profile_like.walk_id = wr.id
where wr.is_public = 1
  and wr.status = 'active'
  and profile_like.user_id = #{currentUserId}

order by profile_like.created_at desc, wr.created_at desc
limit #{limit} offset #{offset}


inner join walk_record_favorites profile_favorite on profile_favorite.walk_id = wr.id
where wr.is_public = 1
  and wr.status = 'active'
  and profile_favorite.user_id = #{currentUserId}

order by profile_favorite.created_at desc, wr.created_at desc
limit #{limit} offset #{offset}
